import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    adj = {}
    for i in range(n):
        a, b = data[1 + 2 * i], data[2 + 2 * i]
        adj.setdefault(a, []).append(b)
    for k in adj:
        adj[k].sort(reverse=True)
    stack = ['JFK']
    route = []
    while stack:
        top = stack[-1]
        lst = adj.get(top)
        if lst:
            stack.append(lst.pop())
        else:
            route.append(stack.pop())
    route.reverse()
    print(' '.join(route))


